// The command line's contract, one spec per command (scripts/lib/args.mjs
// says the shape). bin/agentic-cms.mjs dispatches and prints `--help` from
// it, every script parses its arguments through it, and
// tools/commands-doc.mjs writes docs/commands.md from it — one source, so the
// parser, the help and the docs cannot disagree. Exit codes: 0 clean, 1
// findings or differences, 2 usage or environment.
const root = { type: "string", value: "<dir>", help: "another site tree (its content/ and public/) instead of the current directory" };
const report = (file) => ({ type: "boolean", help: `also write the findings to ${file}` });
const strict = { type: "boolean", help: "every WARN counts as a FAIL" };
const dryRun = { type: "boolean", help: "print what would change; write nothing" };
// A visitor's choice in every page's storage before its scripts run (scripts/lib/storage-seed.mjs): the
// site's src/config/harness.ts, then these pairs over it, key by key.
const seed = {
  storage: { type: "string", multiple: true, value: "<key>=<value>", help: "a localStorage key on the page's origin, written before any of the page's scripts runs, over the site's src/config/harness.ts key by key; {now} in the value is the run's ISO time, {now:ms} its epoch milliseconds" },
  "session-storage": { type: "string", multiple: true, value: "<key>=<value>", help: "the same for sessionStorage" },
  "no-storage": { type: "boolean", help: "leave out the site's seed (the storage areas of src/config/harness.ts; its profile still applies): only the --storage and --session-storage given are seeded (a first visit)" },
};
const seedUsage = "[--storage <key>=<value>]… [--session-storage <key>=<value>]… [--no-storage]";
const seedJson = "seed: { storage, sessionStorage, at } | null";
// A flag without a default yields to the site's profile, src/config/harness.ts (scripts/lib/profile.mjs): a
// default here would be filled in by the parser and always win. Each help names what stands in.
const scheme = (help) => ({ type: "string", choices: ["light", "dark"], help: `${help}; default the first of the profile's schemes (src/config/harness.ts), else light` });
// The lab server's port: lab serve listens on it, urls and setup look for it there.
const LAB_PORT = 8001;
// A route a command writes for the owner, handed over (scripts/lib/handover.mjs): the wait on this clone's running next dev, then its URLs.
const handover = (route) => ({
  "no-wait": { type: "boolean", help: `write it and ask no server (by default, with this clone's next dev running — the one .next/dev/lock names, on whichever port — ${route} is asked until it stops answering 404, which compiles it too, and then its URLs are printed; another server on the port of package.json's scripts.dev is named at once and asked nothing)` },
  timeout: { type: "number", default: 120, value: "<s>", help: `how long ${route} may take to answer, in seconds` },
  url: { type: "string", value: "<base>", help: "the dev server to ask, http://host:port, whatever it is: no lock is read (default: this clone's next dev, on the port its .next/dev/lock names, else localhost on the port of package.json's scripts.dev)" },
  "no-public": { type: "boolean", help: "do not look up the public address for the URLs (offline, or a machine no viewer reaches from outside)" },
});

// The families of commands, in the order of the kit's four layers (docs/parts.md): the content engine's own
// commands, the design tools (which never ship), then the site's commands — its setup, the gates its lint and its
// build run by default, and the steps a site adds to its build. The browser libraries are imports and have no
// commands. The help (bin/agentic-cms.mjs) and docs/commands.md (tools/commands-doc.mjs) list them in this order.
export const FAMILIES = [
  { group: "content", layer: "the content engine" },
  { group: "images", layer: "design tools" },
  { group: "proof", layer: "design tools" },
  { group: "look & measure", layer: "design tools" },
  { group: "icons", layer: "design tools" },
  { group: "lab", layer: "design tools" },
  { group: "demo", layer: "design tools" },
  { group: "site", layer: "the site's commands" },
  { group: "default gates", layer: "the site's commands", about: "what every change passes: `pnpm lint` runs ESLint, then `check-site` (the `check-components` pass first); `pnpm build` runs `pnpm lint`, `lint --production` and `docs --check` (content, above), `next build`, then `seo`, and `guard-email` last on a site whose `src/config/site.ts` turns `guardEmail` on (what `init` writes for a new site); CI runs them on every pull request" },
  { group: "opt-in steps", layer: "the site's commands", about: "what a site adds when it needs them: to its build, `critical-css` for the first paint and `assemble` last for a Node host; to its CI, `pr-preview` for a preview link on every pull request" },
];

